def esc(x):return html.escape(x,quote=True)
def img(brand,key,alt='',cls=''):
 p=A/(brand+'-full-optimized');rows=json.loads((p/'manifest.json').read_text())['assets']; row=next(x for x in rows if x['id']==key or x['name']==key);src=base64.b64encode((p/row['derived_path']).read_bytes()).decode();return f'<img class="{cls}" loading="lazy" src="data:image/webp;base64,{src}" alt="{esc(alt)}">'
def a(url,label,cls='f-btn'):
 return f'<a class="{cls}" href="{esc(url)}" target="_blank" rel="noopener noreferrer">{esc(label)} ↗</a>'
def pills(names,url):return '<div class="f-pills">'+''.join(a(url,n,'f-pill') for n in names)+'</div>'
def footer(brand,url,groups,cls=''):
 return '<footer class="f-foot '+cls+'"><div class="f-wrap f-footgrid"><div><strong>'+esc(brand)+'</strong><p>非官方設計參考</p></div>'+''.join('<div><h3>'+esc(group)+'</h3>'+''.join(a(url,n,'f-footlink') for n in names)+'</div>' for group,names in groups.items())+'</div><div class="f-wrap f-footend">本頁為設計參考，品牌與圖片權利屬原權利人。　'+a(url,'前往官網','f-footlink')+'</div></footer>'
