def linkedin():
 b='linkedin';url='https://www.linkedin.com/'; section=lambda title,desc,content,style='':f'<section class="f-space {style}"><div class="f-wrap f-split"><div><h2>{title}</h2><p>{desc}</p></div>{content}</div></section>'
 topics=section('探索熱門 LinkedIn 內容','從職涯、專業知識與熱門話題中獲得靈感。',pills(['職涯','生產力','金融','科技','領導力','人力資源','行銷','永續發展'],url),'f-topics')
 jobs=section('覓得理想工作或實習機會','',pills(['工程','業務開發','金融','行政助理','零售員','客服','經營管理','資訊科技','行銷','人力資源'],url+'jobs/'))
 post=section('刊登職缺，招募全球菁英！','',a(url+'talent/','刊登職缺'),'f-prompt')
 tools=section('探索最好的軟體工具','透過專業工具完成更多工作。',pills(['電子商務平台','CRM 軟體','人力資源管理系統','專案管理軟體','協作工具'],url))
 games=section('用遊戲激發腦力','休息一下，挑戰新的思考方式。',pills(['Pinpoint','Queens','Crossclimb','Tango','Zip'],url+'games/'))
 feature=section('讓適合人選知道您願意看看其他職缺','透過職涯社群分享你的專業經驗，探索新的機會。',img(b,'dbvmk0tsk0o0hd59fi64z3own','LinkedIn 職涯社群參考圖'),'f-feature')
 people='<section class="f-space"><div class="f-wrap f-people"><article>'+img(b,'43h6n82li4xu0q23s8jqizk6j','交流插圖')+'<h2>結識內部人士</h2>'+a(url+'signup/','尋找認識的人')+'</article><article>'+img(b,'1dhh8rr3wohexkaya6jhn2y8j','學習插圖')+'<h2>學習搶手技能，提升個人競爭力！</h2>'+a(url+'learning/','選擇學習主題')+'</article></div></section>'
 who=section('哪些人應該使用 LinkedIn 呢？','所有想在職涯中前進的人。','<div>'+img(b,'292yd0en6qdvkbezeuj71yu4y','專業人士工作情境')+'</div>','f-who')
 cta='<section class="f-cta"><div class="f-wrap"><h2>與老同學、老同事和老朋友等重拾聯絡</h2>'+a(url+'signup/','立即加入')+'</div></section>'
 return '<main class="f-main li">'+topics+jobs+post+tools+games+feature+people+who+cta+'</main>'+footer('LinkedIn',url,{'一般':['註冊','說明中心','關於'], '瀏覽':['學習','職缺','遊戲'], '商業解決方案':['招募','行銷','銷售'], '目錄':['會員','公司','職務']})
